<script setup>defineProps({ results: Array, loading: Boolean, error: String })</script><template><div class="zhihu-panel"><p v-if="loading" class="empty">正在整理相关讨论…</p><p v-else-if="error" class="empty">{{ error }}</p><template v-else><article v-for="item in results" :key="item.id" class="zhihu-card"><h3><a v-if="item.url" :href="item.url" target="_blank" rel="noopener noreferrer">{{ item.title }}</a><template v-else>{{ item.title }}</template></h3><p>{{ item.excerpt }}</p><small>{{ item.stats }}</small><footer><span>●　<a v-if="item.authorUrl" :href="item.authorUrl" target="_blank" rel="noopener noreferrer" class="zhihu-author">{{ item.author }}</a><template v-else>{{ item.author }}</template>　{{ item.type }}</span><time>{{ item.date }}</time></footer></article><p v-if="!results.length" class="empty">选中古文中的一句话，<br>从知乎探索它背后的知识。</p></template></div></template>
